// The collector (brain/tasks/world-model-data.md → "Infrastructure"): one bot process per bot (collect/bot.ts), a few
// per Paper server; each server's time and weather rotated every 10 minutes and its terrain pre-generated by Chunky.
// Stops at the step target. Measurements per episode go to stdout; coverage counts to <out>/coverage.json.
//   COLLECT_SERVERS='[{"host":"paper-1","port":25565,"rcon":25575,"seed":"123"}]' COLLECT_BOTS=4 node collect/main.ts
import { fork, type ChildProcess } from 'node:child_process'
import { mkdirSync, writeFileSync } from 'node:fs'
import { rconWhenUp, type Rcon } from './rcon.ts'

type Server = { host: string, port?: number, rcon?: number, seed: string }
const env = process.env
const SERVERS: Server[] = JSON.parse(env.COLLECT_SERVERS ?? '[{"host":"localhost","seed":"unknown"}]')
const BOTS = Number(env.COLLECT_BOTS ?? 2) // per server
const TARGET = Number(env.COLLECT_TARGET_STEPS ?? Infinity)
const OUT = env.COLLECT_OUT ?? 'episodes'
const HELDOUT = new Set((env.COLLECT_HELDOUT ?? '').split(',').filter(Boolean))
const PASSWORD = env.COLLECT_RCON_PASSWORD ?? ''
const RADIUS = Number(env.COLLECT_RADIUS ?? 1000)
const ROTATE_MS = 10 * 60_000
const CONDITIONS = [['day', 'clear'], ['night', 'clear'], ['day', 'rain'], ['night', 'rain']]

mkdirSync(OUT, { recursive: true })
let total = 0
let stopping = false
const children = new Map<ChildProcess, string>()
const counts = new Map<string, Record<string, number>>() // per bot: its biome|action|outcome counts
const rcons: Rcon[] = []

function merged () {
  const all: Record<string, number> = {}
  for (const c of counts.values()) for (const [k, n] of Object.entries(c)) all[k] = (all[k] ?? 0) + n
  return all
}

function startBot (s: Server, name: string) {
  const child = fork('collect/bot.ts', [], {
    env: {
      ...env, COLLECT_NAME: name, COLLECT_HOST: s.host, COLLECT_PORT: String(s.port ?? 25565), COLLECT_RCON_PORT: String(s.rcon ?? 25575),
      COLLECT_SEED: s.seed, COLLECT_SPLIT: HELDOUT.has(s.seed) ? 'heldout' : 'train', COLLECT_OUT: OUT, COLLECT_RADIUS: String(RADIUS)
    }
  })
  children.set(child, name)
  child.on('message', (m: { steps: number, wall_ms: number, cpu_ms: number, bytes: number, capture_ms: number, counts: Record<string, number>, biome: string, episode: number }) => {
    total += m.steps
    counts.set(name, m.counts)
    const all = merged()
    for (const c of children.keys()) c.connected && c.send({ counts: all })
    console.log(`[collect] ${name} ep ${m.episode} (${m.biome}): ${m.steps} steps in ${(m.wall_ms / 1000).toFixed(1)} s = ${(m.steps / m.wall_ms * 1000).toFixed(2)} steps/s; ` +
      `cpu ${(m.cpu_ms / m.wall_ms * 100).toFixed(0)}%; capture ${m.capture_ms.toFixed(1)} ms/step; ${(m.bytes / m.steps / 1024).toFixed(2)} KB/step gz; total ${total}`)
    if (total >= TARGET) void stop()
  })
  child.on('exit', code => {
    children.delete(child)
    if (!stopping) { console.log(`[collect] ${name} exited (${code}); restarting in 5 s`); setTimeout(() => startBot(s, name), 5000) }
  })
}

async function setUp (s: Server, i: number) {
  const r = await rconWhenUp(s.host, s.rcon ?? 25575, PASSWORD)
  rcons.push(r)
  // Time and weather stay where the rotation puts them (1.21.11+ rule names).
  for (const cmd of ['gamerule advance_time false', 'gamerule advance_weather false', 'difficulty easy']) await r.command(cmd)
  let k = i // servers start at different points of the rotation
  const rotate = async () => {
    const [time, weather] = CONDITIONS[k++ % CONDITIONS.length]
    await r.command(`time set ${time}`)
    await r.command(`weather ${weather}`)
  }
  await rotate()
  setInterval(() => void rotate().catch(() => {}), ROTATE_MS)
  // Chunky pre-generates the area episodes start in (a no-op where the plugin isn't installed).
  await r.command(`chunky radius ${RADIUS + 128}`)
  const started = await r.command('chunky start')
  console.log(`[collect] ${s.host} chunky start: ${JSON.stringify(started)}`)
  if (/^Unknown/.test(started)) return
  setInterval(() => void r.command('chunky progress').then(p => p && console.log(`[collect] ${s.host} chunky progress: ${p.trim()}`)).catch(() => {}), 60_000)
}

async function stop () {
  if (stopping) return
  stopping = true
  console.log(`[collect] stopping at ${total} steps`)
  for (const c of children.keys()) c.kill('SIGTERM') // each writes its episode so far
  const deadline = Date.now() + 90_000
  while (children.size && Date.now() < deadline) await new Promise(resolve => setTimeout(resolve, 500))
  for (const c of children.keys()) c.kill('SIGKILL')
  writeFileSync(`${OUT}/coverage.json`, JSON.stringify({ steps: total, counts: merged() }, null, 1))
  for (const r of rcons) r.close()
  process.exit(0)
}
process.on('SIGTERM', () => void stop())
process.on('SIGINT', () => void stop())
setInterval(() => writeFileSync(`${OUT}/coverage.json`, JSON.stringify({ steps: total, counts: merged() }, null, 1)), 60_000)

await Promise.all(SERVERS.map(setUp))
SERVERS.forEach((s, i) => { for (let b = 1; b <= BOTS; b++) startBot(s, `C${i + 1}_${b}`) })
